import { Component, createMemo, createSignal, JSX, onCleanup, onMount, Show, splitProps, useContext } from "solid-js";

import { Icon as IconUtils } from "#core/ui/utilities/utilities-image.js";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { RingMeter } from "#core/ui-next/components/ring-meter.jsx";
import { ActionButtonMap } from "#core/ui-next/services/actionButtons.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { HotkeyIconContext } from "#core/ui-next/services/hotkey.js";
import { IsControllerActive, IsHybridActive, useActiveInputContext } from "#core/ui-next/services/input.js";
import { createSignalFromExistingDebugWidget } from "#core/ui-next/utilities/debug-widgets.js";

UI.Debug.registerWidget({
	caption: "Show unknown icons in <NavHelp>",
	category: "Debug",
	domainType: "bool",
	id: "navHelpShowUnknownIcons",
	value: false,
});

export interface NavHelpProps {
	/** Sets the DOM class attribute  */
	class?: string;
	/** The name of the action to show the icon for  */
	actionName?: string;
	/**  Is the nav help disabled (hides the nav help)?  */
	disabled?: boolean;
	/** Use the specified input context instead of the active one. */
	inputContext?: InputContext;
	/** Enables hold animation using a ring meter. */
	isHoldAction?: boolean;
	/** Duration of the hold in milliseconds. Used to drive the ring meter fill animation. */
	holdTimeMs?: number;
}

/** Keys that require the wide keyboard icon asset */
const WIDE_LOC_KEYS = [
	"LOC_OPTIONS_KEY_TAB",
	"LOC_OPTIONS_KEY_CAPSLOCK",
	"LOC_KEYBOARD_SHIFT",
	"LOC_OPTIONS_KEY_LSHIFT",
	"LOC_OPTIONS_KEY_RSHIFT",
	"LOC_KEYBOARD_CTRL",
	"LOC_OPTIONS_KEY_LCONTROL",
	"LOC_OPTIONS_KEY_RCONTROL",
	"LOC_KEYBOARD_ALT",
	"LOC_OPTIONS_KEY_LALT",
	"LOC_OPTIONS_KEY_RALT",
	"LOC_KEYBOARD_ENTER",
	"LOC_OPTIONS_KEY_BACKSPACE",
	"LOC_OPTIONS_KEY_SPACE",
	"LOC_OPTIONS_KEY_DELETE",
	"LOC_OPTIONS_KEY_INSERT",
	"LOC_OPTIONS_KEY_HOME",
	"LOC_OPTIONS_KEY_END",
	"LOC_OPTIONS_KEY_PAGEUP",
	"LOC_OPTIONS_KEY_PAGEDOWN",
	"LOC_KEYBOARD_ESCAPE",
	"LOC_OPTIONS_KEY_LWIN",
	"LOC_OPTIONS_KEY_RWIN",
	"LOC_OPTIONS_KEY_APPS",
	"LOC_OPTIONS_KEY_PRINTSCREEN",
	"LOC_OPTIONS_KEY_PAUSE",
	"LOC_OPTIONS_KEY_NUMLOCK",
	"LOC_OPTIONS_KEY_SCROLLLOCK",
].map((key) => Locale.compose(key));

interface KBMInputInfo {
	/** Type of input: 'keyboard' or 'mouse' */
	deviceType: InputDeviceType.Keyboard | InputDeviceType.Mouse;
	/** The display string for the key (e.g., "T", "SHIFT") */
	displayString: string;
	/** The icon asset name to use */
	iconAsset: string;
	/** Whether the key is considered 'wide' (for styling) */
	isWide: boolean;
}

/**
 * Gets the KBM input information for an action.
 * Returns the input type, display string, and appropriate icon asset.
 */
function getKBMInputInfo(actionName: string): KBMInputInfo | null {
	const actionId = Input.getActionIdByName(actionName);
	if (actionId === null) {
		return null;
	}

	const deviceType = Input.getActionDeviceType(actionId);
	if (deviceType !== InputDeviceType.Keyboard && deviceType !== InputDeviceType.Mouse) {
		return null;
	}

	const displayString = Input.getGestureDisplayString(actionId, 0, deviceType, InputContext.ALL);
	const iconUrl = IconUtils.getIconFromActionID(actionId, deviceType) ?? "";

	if (deviceType === InputDeviceType.Mouse) {
		return {
			deviceType,
			displayString,
			iconAsset: iconUrl,
			isWide: false,
		};
	}

	// It's a keyboard key - determine if it needs the wide icon
	// Compare against localized strings for wide keys
	const isWide = WIDE_LOC_KEYS.some((key) => key === displayString);

	const keyboardIcon = isWide ? "keyboard_icon_key_wide" : "keyboard_icon_key";

	return {
		deviceType,
		displayString,
		iconAsset: keyboardIcon,
		isWide,
	};
}

const NavHelpComponent: Component<NavHelpProps> = (props) => {
	const showUnknownIcons = createSignalFromExistingDebugWidget("navHelpShowUnknownIcons");
	const activeInputContext = useActiveInputContext();
	const iconContext = useContext(HotkeyIconContext);
	const [holdValue, setHoldValue] = createSignal(0);
	let holdStartTime = 0;
	let rafId: number | null = null;

	const inputContext = createMemo(() => {
		return props.inputContext ?? activeInputContext();
	});

	const iconCssUrl = createMemo(() => {
		const actionName = props.actionName ?? iconContext?.actionName();

		if (!actionName) {
			return undefined;
		}

		const gamepadActionName =
			IsControllerActive() || IsHybridActive()
				? (ActionButtonMap.get(actionName.toLowerCase()) ?? actionName)
				: actionName;

		const iconUrl = IconUtils.getIconFromActionName(gamepadActionName, undefined, inputContext()) ?? undefined;
		if (iconUrl && !showUnknownIcons() && iconUrl.includes("icon_mapping_unknown")) {
			return undefined;
		} else {
			return iconUrl ? `url(${iconUrl})` : undefined;
		}
	});

	const isHidden = createMemo(() => {
		const shouldHide =
			(!IsControllerActive() && !IsHybridActive()) ||
			props.disabled ||
			iconContext?.disabled() ||
			iconCssUrl() === undefined;
		return shouldHide;
	});

	onMount(() => {
		if (!props.isHoldAction) {
			return;
		}

		const updateHoldProgress = () => {
			const elapsed = performance.now() - holdStartTime;
			const holdDuration = props.holdTimeMs ?? 1000;
			const progress = Math.min(elapsed / holdDuration, 1) * 100;
			setHoldValue(progress);
			if (progress < 100) {
				rafId = requestAnimationFrame(updateHoldProgress);
			} else {
				rafId = null;
			}
		};

		const handleInputAction = (name: string, status: InputActionStatuses) => {
			const actionName = props.actionName ?? iconContext?.actionName();
			if (name !== actionName) {
				return;
			}
			if (status === InputActionStatuses.START) {
				holdStartTime = performance.now();
				rafId = requestAnimationFrame(updateHoldProgress);
			} else if (status === InputActionStatuses.FINISH) {
				if (rafId !== null) {
					cancelAnimationFrame(rafId);
					rafId = null;
				}
				setHoldValue(0);
			}
		};

		engine.on("InputAction", handleInputAction);
		onCleanup(() => {
			engine.off("InputAction", handleInputAction);
			if (rafId !== null) {
				cancelAnimationFrame(rafId);
				rafId = null;
			}
		});
	});

	return (
		<div
			class={`relative size-8 ${props.class ?? ""}`}
			classList={{ hidden: isHidden() }}
			data-name="NavHelp"
		>
			<Show
				when={props.isHoldAction}
				fallback={
					<Icon
						class="absolute inset-0 size-full"
						name={iconCssUrl()}
						isUrl={true}
					/>
				}
			>
				<RingMeter
					class="absolute -inset-3"
					value={holdValue()}
					max={100}
					animationDuration={32}
				>
					<Icon
						class="size-8"
						name={iconCssUrl()}
						isUrl={true}
					/>
				</RingMeter>
			</Show>
		</div>
	);
};

export type KBMNavHelpProps = JSX.HTMLAttributes<HTMLDivElement> & {
	/** The name of the action to show the icon for */
	actionName: string;
	/** Is the nav help disabled (hides the nav help)? */
	disabled?: boolean;
	isHoldAction?: boolean;
	holdTimeMs?: number;
};

const KBMNavHelpComponent: Component<KBMNavHelpProps> = (props) => {
	const [local, other] = splitProps(props, ["actionName", "isHoldAction", "holdTimeMs", "disabled"]);
	const inputInfo = createMemo(() => getKBMInputInfo(local.actionName));
	const [isHolding, setIsHolding] = createSignal(false);

	const iconCssUrl = createMemo(() => {
		const info = inputInfo();
		if (!info) {
			return undefined;
		}
		return `url(blp:${info.iconAsset})`;
	});

	onMount(() => {
		if (!local.isHoldAction) {
			return;
		}
		const handleInputAction = (name: string, status: InputActionStatuses) => {
			if (name !== local.actionName) {
				return;
			}
			if (status === InputActionStatuses.START) {
				setIsHolding(true);
			} else if (status === InputActionStatuses.FINISH) {
				setIsHolding(false);
			}
		};
		engine.on("InputAction", handleInputAction);
		onCleanup(() => {
			engine.off("InputAction", handleInputAction);
			setIsHolding(false);
		});
	});

	const overlayAnimationDuration = () => {
		if (!local.isHoldAction) {
			return "0ms";
		}

		return `${local.holdTimeMs}ms`;
	};
	return (
		<Show when={inputInfo()}>
			{(info) => (
				<div
					{...other}
					class={`relative h-8 flex items-center justify-center ${other.class ?? ""}`}
					classList={{
						hidden: local.disabled,
						"w-8": !info().isWide,
						"w-14": info().isWide,
						"px-px": info().isWide,
					}}
					data-name="KBMNavHelp"
				>
					<div
						class="relative size-full flex items-center justify-center p-0\.5 bg-contain overflow-hidden"
						style={{ "background-image": iconCssUrl() }}
					>
						<Show when={local.isHoldAction}>
							<div
								class={`absolute pointer-events-none origin-bottom`}
								classList={{
									"inset-1": info().deviceType === InputDeviceType.Keyboard,
									"inset-x-1 inset-y-0\\.5 mx-0\\.5 rounded-lg":
										info().deviceType === InputDeviceType.Mouse,
								}}
								style={{
									"background-color": "rgba(255, 255, 255, 0.3)",
									transform: "scaleY(0)",
									"animation-name": isHolding() ? "kbm-nav-help-hold-fill" : "none",
									"animation-duration": overlayAnimationDuration(),
									"animation-timing-function": "linear",
									"animation-fill-mode": "forwards",
								}}
							/>
						</Show>
						<Show when={info().deviceType === InputDeviceType.Keyboard}>
							<span
								class="relative uppercase text-xs text-center text-accent-1 leading-none"
								style={{
									// eslint-disable-next-line solid/style-prop
									"coh-font-fit-mode": "shrink",
								}}
							>
								{info().displayString}
							</span>
						</Show>
					</div>
				</div>
			)}
		</Show>
	);
};

/**
 * A controller nav help component.
 * Used to display a helper icon for controller input.
 * If actionName is not set, it will attempt to use the hotkey action from the nearest Activatable ancestor (or other HotkeyIconContext).
 * ```tsx
 * // Example - Use icon from button hotkey
 * <Button hotkeyAction="shell-action-1"><NavHelp /></Button>
 * // Example - Specify icon directly
 * <NavHelp actionName="shell-action-1" />
 * ```
 * Default implementation: {@link IconComponent}
 * @param {IconProps} props See {@link IconProps} for a full list of properties
 *
 * Commonly Used Properties:
 * @param {string} props.actionName The name of the action to show the icon for. Default: inherit from HotkeyIconContext
 * @param {string} props.disabled Is the nav help disabled (hides the nav help)? Default: false
 */
export const NavHelp = ComponentRegistry.register("NavHelp", NavHelpComponent);

/**
 * A keyboard/mouse nav help component.
 * Used to display helper icons for keyboard and mouse input.
 * For keyboard keys, displays the key character on top of a keyboard icon asset.
 * For mouse buttons, displays the appropriate mouse icon asset.
 * ```tsx
 * // Example
 * <KBMNavHelp actionName="keyboard-inspect-tooltip" class="size-6" />
 * ```
 * @param {KBMNavHelpProps} props See {@link KBMNavHelpProps} for a full list of properties
 *
 * Commonly Used Properties:
 * @param {string} props.actionName The name of the action to show the icon for (required)
 * @param {string} props.class CSS classes to apply to the component
 * @param {boolean} props.disabled Is the nav help disabled (hides the nav help)? Default: false
 */
export const KBMNavHelp = ComponentRegistry.register("KBMNavHelp", KBMNavHelpComponent);
